-- Database-variables sections (category charts) of Green Drop / Blue Drop / RWQO / IWRM: last point (Sep 2026 monthly, 2025 annual) recomputed as area-weighted mean and as sum
WITH {W}, wl AS (SELECT DISTINCT lower(name) lname, code, prov, area FROM w),
m AS (SELECT wl.code, wl.area, max(temperature) t, max(turbidity) tu, max(ec_salinity) ec, max(tss) tss, max("Ammonia_NH3_N") nh3, max("Total_Inorganic_Nitrogen") tin, max("Total_Phosphorus") tp, max("Heavy_Metals") hm, max("E_coli") ec_, max("Faecal_coliforms") fc, max("Helminth_eggs") he, count(*) n FROM "13.1_wastewater_effluent_quality_master" x JOIN wl ON wl.lname=lower(x.district_name) WHERE year=2026 AND month=9 GROUP BY 1,2)
SELECT '13.1 Sep 2026' t, count(*) n, max(n) rows_per_district, round((sum(area*t)/sum(area))::numeric,2) temperature, round((sum(area*tu)/sum(area))::numeric,2) turbidity, round((sum(area*ec)/sum(area))::numeric,2) ec, round((sum(area*tss)/sum(area))::numeric,2) tss, round((sum(area*nh3)/sum(area))::numeric,2) nh3, round((sum(area*tin)/sum(area))::numeric,2) tin, round((sum(area*tp)/sum(area))::numeric,2) tp, round((sum(area*hm)/sum(area))::numeric,2) hm, round((sum(area*ec_)/sum(area))::numeric,2) ecoli, round((sum(area*fc)/sum(area))::numeric,2) fcoli, round((sum(area*he)/sum(area))::numeric,2) helminth FROM m;;
WITH {W}, wl AS (SELECT DISTINCT lower(name) lname, code, prov, area FROM w),
m AS (SELECT wl.code, wl.area, max(design_capacity) dc, max(inflow_infiltration) ii, max(influent_flow_rate) ifr, max(sludge_production) sp, max(hydraulic_loading_rate) hlr, max(hydraulic_retention_time) hrt, max(power_consumption) pc, count(*) n FROM "13.2_WWTW_operational_master" x JOIN wl ON wl.lname=lower(x.district_name) WHERE year=2026 AND month=9 GROUP BY 1,2)
SELECT '13.2 Sep 2026' t, count(*) n, round(sum(dc)::numeric,2) design_sum, round(sum(ii)::numeric,2) infl_sum, round(sum(ifr)::numeric,2) influent_sum, round(sum(sp)::numeric,2) sludge_sum, round((sum(area*hlr)/sum(area))::numeric,1) hlr_mean, round((sum(area*hrt)/sum(area))::numeric,2) hrt_mean, round((sum(area*pc)/sum(area))::numeric,2) power_mean, round(sum(pc)::numeric,2) power_sum FROM m;;
WITH {W}, wl AS (SELECT DISTINCT lower(name) lname, code, prov, area FROM w),
m AS (SELECT wl.code, wl.area, max("Colour_Value") col, max("Total_Coliforms_Value") tc, max("Nitrate_Value") ni, max("Fluoride_Value") fl, max("Arsenic_Value") ars, max("Total_THMs_Value") thm FROM "14.1_SANS_241_compliance_master" x JOIN wl ON wl.lname=lower(x.district_name) WHERE year=2026 AND month=9 GROUP BY 1,2)
SELECT '14.1 Sep 2026' t, count(*) n, round((sum(area*col)/sum(area))::numeric,2) colour, round((sum(area*tc)/sum(area))::numeric,2) tcoli, round((sum(area*ni)/sum(area))::numeric,2) nitrate, round((sum(area*fl)/sum(area))::numeric,2) fluoride, round((sum(area*ars)/sum(area))::numeric,3) arsenic, round((sum(area*thm)/sum(area))::numeric,3) thms FROM m;;
WITH {W}, wl AS (SELECT DISTINCT lower(name) lname, code, prov, area FROM w),
m AS (SELECT wl.code, wl.area, max(aquatic_habitat_integrity) ahi, max(aspt) aspt, max(ecological_reserve_q) erq, max(fibi) fibi, max(riparian_vegetation) rv, max(CASE WHEN sass5_score >= 0 THEN sass5_score END) sass FROM "15.1_ecological_variables_master" x JOIN wl ON wl.lname=lower(x.district_name) WHERE year=2026 AND month=9 GROUP BY 1,2)
SELECT '15.1 Sep 2026' t, count(*) n, round((sum(area*ahi)/sum(area))::numeric,1) habitat, round((sum(area*aspt)/sum(area))::numeric,3) aspt, round(sum(erq)::numeric,2) eco_reserve_sum, round((sum(area*erq)/sum(area))::numeric,2) eco_reserve_mean, round((sum(area*fibi)/sum(area))::numeric,3) fibi, round((sum(area*rv)/sum(area))::numeric,3) riparian, round((sum(area*sass)/sum(area))::numeric,3) sass5 FROM m;;
WITH {W}, wl AS (SELECT DISTINCT lower(name) lname, code, prov, area FROM w),
m AS (SELECT wl.code, wl.area, max("DO_Value") dov, max("Salinity_Value_TDS") tds, max("Nutrient_Value_TN") tn, max("Nutrient_Value_TP") tp FROM "15.2_chemical_RWQO_variables_master" x JOIN wl ON wl.lname=lower(x.district_name) WHERE year=2026 AND month=9 GROUP BY 1,2)
SELECT '15.2 Sep 2026' t, count(*) n, round((sum(area*dov)/sum(area))::numeric,2) do_, round((sum(area*tds)/sum(area))::numeric,2) tds, round((sum(area*tn)/sum(area))::numeric,2) tn, round((sum(area*tp)/sum(area))::numeric,2) tp FROM m;;
WITH {W}, wl AS (SELECT DISTINCT lower(name) lname, code, prov, area FROM w),
m AS (SELECT wl.code, wl.area, max("Low_Flow_Value") lf, max("Dilution_Value") dil, max("Assimilation_Value") asm FROM "15.3_hydrological_RWQO_variables_master" x JOIN wl ON wl.lname=lower(x.district_name) WHERE year=2026 AND month=9 GROUP BY 1,2)
SELECT '15.3 Sep 2026' t, count(*) n, round(sum(lf)::numeric,2) low_flow_sum, round(sum(dil)::numeric,2) dilution_sum, round((sum(area*asm)/sum(area))::numeric,3) assimilation_mean FROM m;;
WITH {W}, wl AS (SELECT DISTINCT lower(name) lname, code, prov, area FROM w),
m AS (SELECT wl.code, wl.area, max("Mean_Annual_Precipitation_MAP_mm_yr") map, max("Mean_Annual_Evapotranspiration_MAE_mm_yr") mae, max("Mean_Annual_Groundwater_Recharge_mm_yr") rech, max("Climate_Variability_Index_CV_rainfall") cv, max("Mean_Annual_Runoff_MAR_million_m3_yr") mar, max("Inter_Basin_Transfer_Volumes_million_m3_yr") ibt, max("National_Water_Balance_million_m3_yr") nwb, max("Return_Flow_Recycled_Water_million_m3_yr") rf, max("Surface_Water_Availability_Index_ratio") swa, max("Inter_Annual_Storage_Efficiency_pct") ias, max("Groundwater_Dependency_Index_pct") gdi, max("System_Water_Losses_pct") swl, max("Municipal_Water_Demand_L_cap_day") mwd, max("Agricultural_Water_Demand_m3_ha_season") awd, max("Industrial_Water_Demand_m3_yr") iwd, max("Ecological_Reserve_Water_Requirement_m3_yr") erw FROM "16_1_complete_wrm_matrix_master" x JOIN wl ON wl.lname=lower(x.district_name) WHERE year=2025 GROUP BY 1,2)
SELECT '16_1 2025' t, count(*) n, round((sum(area*map)/sum(area))::numeric,2) map, round((sum(area*mae)/sum(area))::numeric,2) mae, round((sum(area*rech)/sum(area))::numeric,2) rech, round((sum(area*cv)/sum(area))::numeric,3) cv, round((sum(area*mar)/sum(area))::numeric,2) mar_mean, round(sum(mar)::numeric,1) mar_sum, round((sum(area*ibt)/sum(area))::numeric,2) ibt_mean, round(sum(ibt)::numeric,1) ibt_sum, round((sum(area*nwb)/sum(area))::numeric,2) nwb_mean, round(sum(nwb)::numeric,1) nwb_sum, round((sum(area*rf)/sum(area))::numeric,2) rf_mean, round(sum(rf)::numeric,1) rf_sum, round((sum(area*swa)/sum(area))::numeric,3) swa, round((sum(area*ias)/sum(area))::numeric,1) ias, round((sum(area*gdi)/sum(area))::numeric,1) gdi, round((sum(area*swl)/sum(area))::numeric,1) swl, round((sum(area*mwd)/sum(area))::numeric,1) mwd, round((sum(area*awd)/sum(area))::numeric,2) awd, round(sum(iwd)::numeric,2) iwd_sum, round(sum(erw)::numeric,2) erw_sum FROM m;;
-- Overview: drought-area over 24 months, Sep 2024 shares (SPI-6 classes)
WITH {W}, s AS (SELECT w.code, w.area, round("SPI_6_Medium_Term_Hydrological_Impacts"::numeric,2) v FROM "6.2_rainfall_derived_drought_indices_master" t JOIN w ON w.name=t."District_Name" WHERE "Year"=2024 AND "Month"=9),
c AS (SELECT area, CASE WHEN v <= -2.0 THEN 'D4' WHEN v <= -1.6 THEN 'D3' WHEN v <= -1.3 THEN 'D2' WHEN v <= -0.8 THEN 'D1' WHEN v <= -0.5 THEN 'D0' ELSE 'None' END cls FROM s)
SELECT cls, round((100*sum(area)/1222435.4)::numeric,1) pct FROM c GROUP BY 1 ORDER BY 1;;
